import type { ComponentType } from "react"
import { useEffect, useRef } from "react"

// While the cursor is over the project row, turn vertical mouse-wheel scrolling into a smooth
// sideways glide through the projects. The page itself stays still while hovering the row,
// even at the first or last project.
export function withWheelScroll(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLElement | null>(null)

        useEffect(() => {
            const el = ref.current
            if (!el) return
            // opt this row out of page smooth-scroll libraries (e.g. Lenis) that listen on the window
            el.setAttribute("data-lenis-prevent", "")
            // never chain scrolling from this row to the page
            el.style.overscrollBehavior = "contain"
            let target = el.scrollLeft
            let frame = 0

            const animate = () => {
                const diff = target - el.scrollLeft
                if (Math.abs(diff) < 0.5) {
                    el.scrollLeft = target
                    frame = 0
                    return
                }
                el.scrollLeft += diff * 0.18
                frame = requestAnimationFrame(animate)
            }

            const onWheel = (event: WheelEvent) => {
                // let trackpad sideways swipes behave natively
                if (Math.abs(event.deltaX) > Math.abs(event.deltaY)) return
                const max = el.scrollWidth - el.clientWidth
                if (max <= 0) return
                if (!frame) target = el.scrollLeft
                const delta = event.deltaMode === 1 ? event.deltaY * 32 : event.deltaY
                const atStart = target <= 0 && delta < 0
                const atEnd = target >= max - 1 && delta > 0
                event.preventDefault() // keep the page still while hovering the row
                event.stopPropagation()
                if (atStart || atEnd) return
                target = Math.max(0, Math.min(max, target + delta * 1.2))
                if (!frame) frame = requestAnimationFrame(animate)
            }

            el.addEventListener("wheel", onWheel, { passive: false })
            return () => {
                el.removeEventListener("wheel", onWheel)
                if (frame) cancelAnimationFrame(frame)
            }
        }, [])

        return <Component {...props} ref={ref} />
    }
}

