import type { ComponentType } from "react"
import { useEffect, useRef } from "react"

const STYLE_ID = "jl-text-wave-style"
const CSS = `
@keyframes jl-text-wave {
    0%   { transform: translateY(0) scaleY(1); }
    4%   { transform: translateY(-0.2em) scaleY(1.06); }
    8%   { transform: translateY(0.04em) scaleY(0.97); }
    12%  { transform: translateY(0) scaleY(1); }
    100% { transform: translateY(0) scaleY(1); }
}
.jl-wave-char {
    display: inline-block;
    white-space: pre;
    transform-origin: 50% 100%;
    animation: jl-text-wave 5s cubic-bezier(0.32, 0.72, 0, 1) infinite;
    will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
    .jl-wave-char { animation: none; }
}
`

// Ripples the text letter by letter when the page opens, then again every 5 seconds.
export function withWave(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLElement | null>(null)

        useEffect(() => {
            const root = ref.current
            if (!root || typeof document === "undefined") return
            if (!document.getElementById(STYLE_ID)) {
                const style = document.createElement("style")
                style.id = STYLE_ID
                style.textContent = CSS
                document.head.appendChild(style)
            }
            if (root.querySelector(".jl-wave-char")) return

            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
            const textNodes: Text[] = []
            while (walker.nextNode()) textNodes.push(walker.currentNode as Text)

            let index = 0
            for (const node of textNodes) {
                const text = node.textContent || ""
                if (!text.trim()) continue
                const frag = document.createDocumentFragment()
                for (const ch of Array.from(text)) {
                    const span = document.createElement("span")
                    span.className = "jl-wave-char"
                    span.textContent = ch
                    span.style.animationDelay = (index * 0.045).toFixed(3) + "s"
                    span.setAttribute("aria-hidden", "true")
                    frag.appendChild(span)
                    index++
                }
                node.parentNode?.replaceChild(frag, node)
            }
            root.setAttribute("aria-label", textNodes.map((n) => n.textContent).join("") || root.textContent || "")
        })

        return <Component {...props} ref={ref} />
    }
}

