import type { ComponentType } from "react"
import { useEffect, useRef } from "react"

const EMAIL = "jackluk518@gmail.com"

// Small pill message that slides up from the bottom of the screen, then fades away.
function toast(message: string) {
    if (typeof document === "undefined") return
    document.getElementById("jl-toast")?.remove()
    const el = document.createElement("div")
    el.id = "jl-toast"
    el.setAttribute("role", "status")
    el.textContent = message
    Object.assign(el.style, {
        position: "fixed",
        left: "50%",
        bottom: "32px",
        transform: "translate(-50%, 16px)",
        opacity: "0",
        background: "#141414",
        color: "#fff",
        font: "500 14px/1.2 Inter, system-ui, sans-serif",
        padding: "12px 18px",
        borderRadius: "999px",
        boxShadow: "0 10px 30px rgba(0, 0, 0, 0.18)",
        zIndex: "10000",
        pointerEvents: "none",
        transition: "opacity 0.25s ease, transform 0.25s ease",
    } as Partial<CSSStyleDeclaration>)
    document.body.appendChild(el)
    requestAnimationFrame(() => {
        el.style.opacity = "1"
        el.style.transform = "translate(-50%, 0)"
    })
    window.setTimeout(() => {
        el.style.opacity = "0"
        el.style.transform = "translate(-50%, 16px)"
        window.setTimeout(() => el.remove(), 300)
    }, 1800)
}

async function copyText(text: string) {
    try {
        await navigator.clipboard.writeText(text)
        return true
    } catch {
        // older browsers: copy through a hidden text field
        try {
            const area = document.createElement("textarea")
            area.value = text
            area.style.position = "fixed"
            area.style.opacity = "0"
            document.body.appendChild(area)
            area.select()
            const ok = document.execCommand("copy")
            area.remove()
            return ok
        } catch {
            return false
        }
    }
}

// Clicking the email button copies the address and shows "Email copied". If copying is blocked,
// it falls back to opening the visitor's mail app.
export function withCopyEmail(Component: ComponentType<any>): ComponentType {
    return (props: any) => (
        <Component
            {...props}
            role="button"
            tabIndex={0}
            title="Copy email address"
            aria-label={`Copy email address (${EMAIL})`}
            onClick={async (event: any) => {
                event?.preventDefault?.()
                props.onClick?.(event)
                if (await copyText(EMAIL)) toast("Email copied: " + EMAIL)
                else window.location.href = "mailto:" + EMAIL
            }}
            onKeyDown={(event: any) => {
                if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault()
                    event.currentTarget.click()
                }
            }}
        />
    )
}

// Side-by-side screenshot pairs are a single image: two equal halves with a 36px transparent gap
// between them, built at these total widths.
const PAIR_WIDTHS = [1836, 2836]
const PAIR_GAP = 36

// Full-screen viewer for one image. Click anywhere, press Esc or use the close button to dismiss.
// For a side-by-side pair, only the half that was clicked is shown.
function openLightbox(img: HTMLImageElement, clickX?: number) {
    const overlay = document.createElement("div")
    overlay.setAttribute("role", "dialog")
    overlay.setAttribute("aria-modal", "true")
    overlay.setAttribute("aria-label", img.alt || "Enlarged image")
    overlay.setAttribute("data-lenis-prevent", "")
    Object.assign(overlay.style, {
        position: "fixed",
        inset: "0",
        zIndex: "10000",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "48px 24px",
        boxSizing: "border-box",
        background: "rgba(10, 10, 10, 0.88)",
        backdropFilter: "blur(4px)",
        cursor: "zoom-out",
        opacity: "0",
        transition: "opacity 0.22s ease",
    } as Partial<CSSStyleDeclaration>)

    const big = document.createElement("img")
    // the full-size original (the page may be showing a scaled-down version)
    const original = (img.currentSrc || img.src).split("?")[0]
    big.src = original
    big.alt = img.alt
    const rect = img.getBoundingClientRect()
    const leftHalf = clickX === undefined || clickX - rect.left < rect.width / 2
    Object.assign(big.style, {
        maxWidth: "100%",
        maxHeight: "100%",
        objectFit: "contain",
        borderRadius: "12px",
        boxShadow: "0 20px 60px rgba(0, 0, 0, 0.45)",
        transform: "scale(0.96)",
        transition: "transform 0.22s ease",
        // diagrams are drawn on a transparent background, so give them a white card
        background: /\.svg(\?|$)/i.test(big.src) ? "#fff" : "transparent",
        padding: /\.svg(\?|$)/i.test(big.src) ? "24px" : "0",
        boxSizing: "border-box",
    } as Partial<CSSStyleDeclaration>)

    const close = document.createElement("button")
    close.type = "button"
    close.setAttribute("aria-label", "Close")
    close.textContent = "✕"
    Object.assign(close.style, {
        position: "absolute",
        top: "16px",
        right: "16px",
        width: "40px",
        height: "40px",
        borderRadius: "999px",
        border: "none",
        background: "rgba(255, 255, 255, 0.14)",
        color: "#fff",
        font: "500 18px/1 Inter, system-ui, sans-serif",
        cursor: "pointer",
    } as Partial<CSSStyleDeclaration>)

    // `shown` is what animates in: the image itself, or a window onto one half of a pair
    let shown: HTMLElement = big
    overlay.appendChild(big)
    overlay.appendChild(close)
    document.body.appendChild(overlay)

    // keep the image hidden until we know whether it's a pair, so both halves never flash up
    big.style.visibility = "hidden"
    const framePairHalf = () => {
        big.style.visibility = "visible"
        const w = big.naturalWidth
        const h = big.naturalHeight
        if (!PAIR_WIDTHS.includes(w) || !h) return
        const half = (w - PAIR_GAP) / 2
        const aspect = half / h
        const frame = document.createElement("div")
        Object.assign(frame.style, {
            position: "relative",
            overflow: "hidden",
            borderRadius: "12px",
            boxShadow: "0 20px 60px rgba(0, 0, 0, 0.45)",
            aspectRatio: `${half} / ${h}`,
            width: `min(100%, calc((100vh - 96px) * ${aspect}))`,
            transform: big.style.transform,
            transition: "transform 0.22s ease",
        } as Partial<CSSStyleDeclaration>)
        Object.assign(big.style, {
            position: "absolute",
            top: "0",
            left: leftHalf ? "0" : `${(-(half + PAIR_GAP) / half) * 100}%`,
            width: `${(w / half) * 100}%`,
            height: "100%",
            maxWidth: "none",
            maxHeight: "none",
            borderRadius: "0",
            boxShadow: "none",
            transform: "none",
            transition: "none",
        } as Partial<CSSStyleDeclaration>)
        overlay.insertBefore(frame, big)
        frame.appendChild(big)
        shown = frame
    }
    if (big.complete) framePairHalf()
    else {
        big.addEventListener("load", framePairHalf, { once: true })
        big.addEventListener("error", () => (big.style.visibility = "visible"), { once: true })
    }

    const prevOverflow = document.documentElement.style.overflow
    document.documentElement.style.overflow = "hidden"
    requestAnimationFrame(() => {
        overlay.style.opacity = "1"
        shown.style.transform = "scale(1)"
    })
    close.focus({ preventScroll: true })

    const dismiss = () => {
        window.removeEventListener("keydown", onKey)
        overlay.style.opacity = "0"
        shown.style.transform = "scale(0.96)"
        document.documentElement.style.overflow = prevOverflow
        window.setTimeout(() => overlay.remove(), 230)
    }
    const onKey = (event: KeyboardEvent) => {
        if (event.key === "Escape") dismiss()
    }
    overlay.addEventListener("click", dismiss)
    window.addEventListener("keydown", onKey)
}

// Makes every picture inside a block of text (e.g. a project write-up) open full-screen on click.
export function withLightbox(Component: ComponentType<any>): ComponentType {
    return (props: any) => {
        const ref = useRef<HTMLDivElement | null>(null)

        useEffect(() => {
            const root = ref.current
            if (!root) return
            const style = document.createElement("style")
            style.textContent = "[data-jl-lightbox] img { cursor: zoom-in; }"
            document.head.appendChild(style)

            const onClick = (event: MouseEvent) => {
                const img = (event.target as HTMLElement)?.closest?.("img") as HTMLImageElement | null
                if (!img || !root.contains(img)) return
                event.preventDefault()
                openLightbox(img, event.clientX)
            }
            root.addEventListener("click", onClick)
            return () => {
                root.removeEventListener("click", onClick)
                style.remove()
            }
        }, [])

        // "display: contents" keeps the text block laid out exactly as before
        return (
            <div ref={ref} data-jl-lightbox="" style={{ display: "contents" }}>
                <Component {...props} />
            </div>
        )
    }
}
